import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()

    val from = IntArray(m)
    val to = IntArray(m)

    for (i in 0 until m) {
        from[i] = fs.nextInt() - 1
        to[i] = fs.nextInt() - 1
    }

    var assignments = 1
    repeat(n) { assignments *= 6 }

    val colors = IntArray(n)
    var answer = 0

    for (assignment in 0 until assignments) {
        var value = assignment
        for (v in 0 until n) {
            colors[v] = value % 6
            value /= 6
        }

        var usedTypes = 0L
        for (i in 0 until m) {
            val a = colors[from[i]]
            val b = colors[to[i]]
            val low = minOf(a, b)
            val high = maxOf(a, b)
            val type = low * 6 + high
            usedTypes = usedTypes or (1L shl type)
        }

        answer = maxOf(answer, java.lang.Long.bitCount(usedTypes))
