import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value * sign
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()

    val u = IntArray(m)
    val v = IntArray(m)
    repeat(m) {
        u[it] = fs.nextInt() - 1
        v[it] = fs.nextInt() - 1
    }

    val pairIndex = Array(6) { IntArray(6) }
    var index = 0
    for (a in 0 until 6) {
        for (b in a until 6) {
            pairIndex[a][b] = index
            pairIndex[b][a] = index
            index++
        }
    }

    var assignments = 1
    repeat(n) { assignments *= 6 }

    val color = IntArray(n)
    var answer = 0

    for (state in 0 until assignments) {
        var x = state
        for (i in 0 until n) {
            color[i] = x % 6
            x /= 6
        }

        var mask = 0
        for (i in 0 until m) {
            val type = pairIndex[color[u[i]]][color[v[i]]]
            mask = mask or (1 shl type)
        }

        answer = maxOf(answer, Integer.bitCount(mask))
    }

    print(answer)
}

